with f as (select count(*) filter(where p.prosecdef) secdef,count(*) filter(where p.prosecdef and coalesce(array_to_string(p.proconfig,','),'') like '%search_path=""%') safe_path,count(*) total from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('m029_owned_reference_exists','m029_append_event','save_personal_operational_record_v2','save_canonical_domain_draft','save_canonical_domain_object','archive_canonical_domain_object','link_canonical_domain_objects','convert_canonical_domain_object')),e as(select count(*) n from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='extensions' and p.proname in('digest','gen_random_uuid')) select jsonb_build_object('result',case when f.total=8 and f.secdef=8 and f.safe_path=8 and e.n>=2 then 'M029_NAMESPACE_COMPATIBILITY_PASS' else 'FAIL' end,'functions',f.total,'security_definer',f.secdef,'safe_search_path',f.safe_path,'extension_functions',e.n) verification from f,e;
